class Solution:
    def effectiveSubsequences(self, nums):
        MOD = 10 ** 9 + 7
        T = 0
        for x in nums:
            T |= x
        bits = [b for b in range(20) if (T >> b) & 1]
        nb = len(bits)
        n = len(nums)
        bad = 0
        for S in range(1 << nb):
            mask = 0
            for j in range(nb):
                if (S >> j) & 1:
                    mask |= 1 << bits[j]
            f = sum(1 for x in nums if x & mask == 0)
            term = pow(2, f, MOD)
            if bin(S).count('1') % 2:
                bad -= term
            else:
                bad += term
        return (pow(2, n, MOD) - bad) % MOD

