class Solution {
public:
    int effectiveSubsequences(vector<int>& nums) {
        const long long MOD = 1e9 + 7;
        int T = 0;
        for (int x : nums) T |= x;
        vector<int> bits;
        for (int b = 0; b < 20; b++)
            if (T >> b & 1) bits.push_back(b);
        int nb = bits.size(), n = nums.size();
        long long bad = 0;
        auto pw = [&](long long e) {
            long long r = 1, b = 2;
            while (e) { if (e & 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; }
            return r;
        };
        for (int S = 0; S < (1 << nb); S++) {
            int mask = 0;
            for (int j = 0; j < nb; j++)
                if (S >> j & 1) mask |= 1 << bits[j];
            long long f = 0;
            for (int x : nums) if ((x & mask) == 0) f++;
            long long term = pw(f);
            if (__builtin_popcount(S) & 1) bad -= term;
            else bad += term;
        }
        long long ans = (pw(n) - bad) % MOD;
        return (int)((ans + MOD) % MOD);
    }
};

