class Solution {
    public int effectiveSubsequences(int[] nums) {
        final long MOD = 1000000007L;
        int T = 0;
        for (int x : nums) T |= x;
        List<Integer> bits = new ArrayList<>();
        for (int b = 0; b < 20; b++)
            if (((T >> b) & 1) == 1) bits.add(b);
        int nb = bits.size(), n = nums.length;
        long bad = 0;
        for (int S = 0; S < (1 << nb); S++) {
            int mask = 0;
            for (int j = 0; j < nb; j++)
                if (((S >> j) & 1) == 1) mask |= 1 << bits.get(j);
            long f = 0;
            for (int x : nums) if ((x & mask) == 0) f++;
            long term = modpow(2, f, MOD);
            if (Integer.bitCount(S) % 2 == 1) bad -= term;
            else bad += term;
        }
        long ans = (modpow(2, n, MOD) - bad) % MOD;
        return (int)((ans + MOD) % MOD);
    }
    private long modpow(long b, long e, long m) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = r * b % m;
            b = b * b % m;
            e >>= 1;
        }
        return r;
    }
}

