var effectiveSubsequences = function(nums) {
    const MOD = 1000000007n;
    let T = 0;
    for (const x of nums) T |= x;
    const bits = [];
    for (let b = 0; b < 20; b++) if ((T >> b) & 1) bits.push(b);
    const nb = bits.length, n = BigInt(nums.length);
    let bad = 0n;
    const pw = e => { let r = 1n, b = 2n; while (e > 0n) { if (e & 1n) r = r * b % MOD; b = b * b % MOD; e >>= 1n; } return r; };
    for (let S = 0; S < (1 << nb); S++) {
        let mask = 0;
        for (let j = 0; j < nb; j++) if ((S >> j) & 1) mask |= 1 << bits[j];
        let f = 0n;
        for (const x of nums) if ((x & mask) === 0) f++;
        const term = pw(f);
        let pc = 0;
        for (let t = S; t; t >>= 1) pc += t & 1;
        if (pc % 2) bad -= term; else bad += term;
    }
    return Number(((pw(n) - bad) % MOD + MOD) % MOD);
};
